export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"vi","term":"Coin và token (Coin vs token)","aka":["coin","token","phân biệt coin và token"],"short":"Coin là tài sản gốc của một blockchain riêng như BTC hay ETH, còn token là tài sản được tạo trên một blockchain có sẵn thông qua hợp đồng thông minh, như USDT trên Ethereum hay Tron.","body":[["Coin vận hành chính ",["blockchain","blockchain"]," của nó: dùng để trả phí giao dịch, thưởng cho thợ đào hoặc ",["validator","validator"]," và bảo vệ mạng. ",["BTC","bitcoin"]," trên Bitcoin, ",["ETH","ethereum"]," trên Ethereum, SOL trên Solana đều là coin."],["Token thì mượn hạ tầng của một chuỗi khác. Một dự án viết ",["hợp đồng thông minh","smart-contract"]," theo chuẩn như ERC-20 hay SPL là có thể phát hành token mà không cần xây blockchain mới. Token có thể là ",["stablecoin","stablecoin"],", token quản trị, token của trò chơi hoặc memecoin."],"Điều này ảnh hưởng trực tiếp khi bạn chuyển tiền: muốn gửi token trên Ethereum, bạn cần ETH để trả phí gas. Một token cũng có thể tồn tại trên nhiều mạng, nên khi rút bạn phải chọn đúng mạng mà ví nhận hỗ trợ. Trong giao tiếp hàng ngày, nhiều người vẫn gọi chung tất cả là coin."],"example":"Giả sử ví của bạn trên mạng Ethereum có 200 USDT và 0 ETH. Bạn không thể gửi số USDT này đi, vì phí gas phải trả bằng ETH chứ không trả bằng USDT. Nếu bạn nạp thêm 0,005 ETH và mỗi lần chuyển token tốn khoảng 0,001 ETH, bạn có đủ phí cho khoảng 5 lần chuyển. Còn nếu cùng 200 USDT nằm trên mạng Tron, bạn sẽ cần TRX để trả phí.","mistakes":["Không giữ coin gốc trong ví nên không trả được phí khi muốn chuyển token.","Nghĩ rằng USDT trên Ethereum và USDT trên Tron có thể gửi qua lại trực tiếp mà không cần đúng mạng.","Tin rằng token nào cũng kém giá trị hơn coin, trong khi đây chỉ là khác biệt kỹ thuật."],"faq":[{"q":"USDT là coin hay token?","a":"USDT là token, vì nó được phát hành bằng hợp đồng thông minh trên nhiều blockchain như Ethereum, Tron và các mạng khác, chứ không có blockchain riêng."},{"q":"Một token có thể trở thành coin không?","a":"Có. Một số dự án ban đầu phát hành token trên Ethereum, sau đó ra mắt blockchain riêng và chuyển đổi token sang coin gốc của chuỗi mới."}],"title":"Coin và token khác nhau thế nào? Giải thích dễ hiểu","description":"Phân biệt coin và token trong crypto, vì sao cần coin gốc để trả phí gas và cách chọn đúng mạng khi chuyển token.","related":[["layer-1","Layer 1 (L1, blockchain lớp 1)","Layer 1 (L1) là blockchain nền tảng tự xử lý và xác nhận giao dịch bằng cơ chế đồng thuận riêng, có coin gốc riêng, như Bitcoin, Ethereum, Solana hay BNB Chain."],["smart-contract","Hợp đồng thông minh (Smart contract)","Hợp đồng thông minh (smart contract) là chương trình được triển khai trên blockchain, tự động thực hiện các điều kiện đã lập trình khi có giao dịch gọi tới mà không cần bên trung gian."],["governance-token","Token quản trị (Governance token)","Token quản trị là token cho người nắm giữ quyền đề xuất và bỏ phiếu về các thay đổi của một giao thức hay DAO, ví dụ UNI của Uniswap hay AAVE của Aave."],["tokenomics","Tokenomics (kinh tế học token)","Tokenomics là toàn bộ thiết kế kinh tế của một token: tổng cung, cách phân bổ, lịch mở khóa, cơ chế phát hành và đốt, cùng công dụng khiến người dùng cần giữ hoặc dùng token đó."],["altcoin","Altcoin","Altcoin là cách gọi chung mọi đồng tiền mã hóa không phải Bitcoin, từ các dự án lớn như Ethereum, Solana đến những token nhỏ mới niêm yết."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"vi","term":"Memecoin (meme coin)","aka":["meme coin","coin meme","memecoin"],"short":"Memecoin là đồng tiền mã hóa lấy cảm hứng từ meme, trò đùa hay văn hóa mạng, giá trị chủ yếu đến từ cộng đồng và sự chú ý thay vì sản phẩm hay dòng tiền thực.","body":["Dogecoin, ra đời năm 2013 từ meme chú chó Shiba, là memecoin nổi tiếng nhất. Sau đó có Shiba Inu, Pepe và rất nhiều token khác. Ngày nay, bất kỳ ai cũng có thể tạo memecoin trên Solana, Base hay BNB Chain chỉ trong vài phút.",["Giá memecoin có thể tăng hàng chục lần rồi giảm hơn 90% trong thời gian ngắn. ",["Thanh khoản","liquidity"]," thường mỏng, nhóm ví lớn nắm phần đáng kể nguồn cung, và chỉ một tin đồn trên mạng xã hội cũng đủ làm giá ",["biến động","volatility"]," mạnh."],["Rủi ro lớn nhất là ",["rug pull","rug-pull"],": người tạo rút hết thanh khoản hoặc bán sạch phần của mình. Trước khi mua, hãy xem tỷ lệ nắm giữ của các ví lớn nhất, thanh khoản đã khóa chưa, hợp đồng có cho phép chặn bán hay đúc thêm không. Chỉ dùng số tiền bạn chấp nhận mất toàn bộ."]],"example":["Giả sử bạn mua một memecoin với 100 ",["USDT","usdt"]," trên ",["DEX","dex"],", chịu ",["trượt giá","slippage"]," 3% nên thực tế nhận lượng token trị giá khoảng 97 USDT. Giá tăng gấp 3 rồi giảm 80% từ đỉnh. Phần của bạn đi từ 97 lên 291 USDT, rồi còn khoảng 58 USDT. Khi bán, thanh khoản mỏng khiến bạn trượt thêm 5%, còn khoảng 55 USDT. Nếu không có kế hoạch chốt lời, đợt tăng gấp 3 không giúp gì cho bạn."],"mistakes":["Mua memecoin ngay khi thấy video hoặc nhóm chat hô hào mà không kiểm tra hợp đồng.","Đặt trượt giá cho phép quá cao trên DEX và bị bot chèn lệnh.","Không có kế hoạch chốt lời hay cắt lỗ với một tài sản biến động cực mạnh."],"faq":[{"q":"Memecoin có giá trị thực không?","a":"Phần lớn memecoin không có sản phẩm hay doanh thu, giá trị dựa vào cộng đồng và sự chú ý. Một số có cộng đồng lâu năm và thanh khoản lớn, nhưng vẫn biến động rất mạnh."},{"q":"Làm sao nhận biết memecoin rug pull?","a":"Dấu hiệu thường gặp là vài ví nắm phần lớn nguồn cung, thanh khoản không khóa, hợp đồng cho phép đúc thêm hoặc chặn bán, và đội ngũ ẩn danh hứa hẹn lợi nhuận."}],"title":"Memecoin là gì? Ý nghĩa và rủi ro coin meme","description":"Memecoin là gì, vì sao Dogecoin hay Pepe biến động mạnh, rug pull là gì và cần kiểm tra gì trước khi mua coin meme.","related":[["altcoin","Altcoin","Altcoin là cách gọi chung mọi đồng tiền mã hóa không phải Bitcoin, từ các dự án lớn như Ethereum, Solana đến những token nhỏ mới niêm yết."],["rug-pull","Rug pull (Rút thảm)","Rug pull là khi đội ngũ dự án crypto đột ngột rút thanh khoản, bán tháo token hoặc biến mất cùng tiền của nhà đầu tư, khiến giá token gần như về 0."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."],["liquidity","Thanh khoản (Liquidity)","Thanh khoản là mức độ dễ dàng mua hoặc bán một tài sản với số lượng lớn mà giá không bị đẩy đi nhiều."],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"vi","term":"HODL (giữ dài hạn)","aka":["HODL","hold","holder","giữ coin dài hạn"],"short":"HODL là cách nói trong cộng đồng crypto chỉ việc giữ tài sản lâu dài bất chấp biến động ngắn hạn, bắt nguồn từ một lỗi chính tả của chữ hold trên diễn đàn Bitcoin năm 2013.","body":["Chữ HODL xuất hiện trong một bài đăng trên diễn đàn Bitcointalk khi giá đang giảm mạnh, và người viết gõ sai hold thành hodl. Về sau, cộng đồng còn diễn giải nó là Hold On for Dear Life, tức giữ chặt dù chuyện gì xảy ra.",["HODL là chiến lược nắm giữ dài hạn, ít giao dịch, tránh bán trong hoảng loạn. Nó thường đi kèm mua định kỳ (",["DCA","dollar-cost-averaging"],") và lưu trữ coin trong ",["ví lạnh","cold-wallet"],". Ưu điểm là giảm phí giao dịch và quyết định cảm tính; nhược điểm là bạn phải chịu toàn bộ các đợt giảm sâu."],["HODL chỉ hợp lý với tài sản bạn hiểu rõ và tin có giá trị lâu dài. Giữ mãi một ",["altcoin","altcoin"]," đã mất ",["thanh khoản","liquidity"]," không phải là chiến lược, mà là bỏ quên rủi ro. Hãy xem lại định kỳ lý do bạn nắm giữ."]],"example":["Giả sử bạn mua 0,1 ",["BTC","bitcoin"]," ở 40.000 ",["USDT","usdt"],", tổng 4.000 USDT, và quyết định HODL. Trong năm đầu giá giảm xuống 24.000 USDT, phần của bạn chỉ còn 2.400 USDT, lỗ tạm 40%. Nếu bạn giữ được và giá sau đó lên 56.000 USDT, phần đó trị giá 5.600 USDT, lãi 40% so với vốn. Nếu bạn bán hoảng loạn ở 24.000, bạn đã khóa khoản lỗ 1.600 USDT."],"mistakes":["HODL bằng tiền vay hoặc tiền cần dùng trong ngắn hạn.","Giữ coin dài hạn trên một sàn duy nhất mà không cân nhắc ví tự lưu ký.","Áp dụng HODL cho mọi altcoin mà không xem lại dự án còn hoạt động hay không."],"faq":[{"q":"HODL nghĩa là gì?","a":"HODL nghĩa là giữ tài sản crypto lâu dài thay vì mua bán liên tục. Đây là một lỗi chính tả của chữ hold đã trở thành thuật ngữ phổ biến."},{"q":"HODL có tốt hơn trading không?","a":"Hai cách phù hợp với mục tiêu và khả năng khác nhau. HODL ít tốn thời gian và phí hơn, nhưng bạn phải chịu được các đợt giảm sâu mà không bán."}],"title":"HODL là gì? Ý nghĩa và nguồn gốc HODL","description":"HODL là gì, nguồn gốc từ lỗi chính tả năm 2013, ưu nhược điểm của chiến lược giữ dài hạn và khi nào nó không hợp lý.","related":[["dollar-cost-averaging","DCA (Trung bình giá)","DCA (dollar-cost averaging) là chiến lược mua một số tiền cố định của một tài sản theo lịch đều đặn, bất kể giá lên hay xuống, để làm mềm tác động của biến động giá."],["cold-wallet","Ví lạnh (Cold wallet)","Ví lạnh là cách lưu khóa riêng tư hoàn toàn ngoại tuyến, ví dụ trên ví cứng hoặc thiết bị không bao giờ kết nối mạng, để giảm tối đa rủi ro bị hack từ xa."],["bear-market","Thị trường giảm giá (Bear market)","Thị trường giảm giá (bear market) là giai đoạn giá giảm kéo dài, thường hơn 20% từ đỉnh, kèm tâm lý bi quan, khối lượng giao dịch thấp và dòng tiền rút khỏi thị trường."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"vi","term":"Pool thanh khoản (Liquidity pool)","aka":["liquidity pool","LP","bể thanh khoản","pool"],"short":"Pool thanh khoản là kho token được khóa trong hợp đồng thông minh, do nhiều người cùng góp vào, để người khác giao dịch, vay hoặc swap, đổi lại người góp nhận một phần phí.","body":[["Trên ",["DEX","dex"]," dùng ",["AMM","amm"],", mỗi ",["cặp giao dịch","trading-pair"]," như ",["ETH","ethereum"],"/",["USDC","usdc"]," là một pool. Người cung cấp ",["thanh khoản","liquidity"]," (LP) gửi hai token theo tỷ lệ giá trị hiện tại và nhận token LP hoặc NFT vị thế làm biên nhận. Khi rút, bạn đổi biên nhận lấy phần token tương ứng trong pool cộng phí tích lũy."],"Thu nhập của LP đến từ phí giao dịch, đôi khi cộng thêm token thưởng. Rủi ro gồm: tổn thất tạm thời khi giá hai token lệch nhau, lỗi hợp đồng thông minh, và với token mới thì rủi ro rug pull khi đội ngũ rút thanh khoản.","Độ sâu của pool quyết định trải nghiệm của người giao dịch: pool càng lớn, trượt giá càng thấp. Đó là lý do nhiều dự án trả thưởng để thu hút thanh khoản."],"example":"Giả sử pool ETH/USDC có 100 ETH và 300.000 USDC. Bạn góp 1 ETH và 3.000 USDC, chiếm 1 phần 101, khoảng 0,99% pool. Phí giao dịch là 0,3% và khối lượng một ngày là 1.000.000 USDC, tạo ra 3.000 USDC phí. Phần của bạn khoảng 29,7 USDC trong ngày đó, trước khi tính tổn thất tạm thời nếu giá ETH thay đổi.","mistakes":["Chỉ nhìn APR phí mà bỏ qua tổn thất tạm thời có thể lớn hơn phí thu được.","Góp thanh khoản cho token mới chưa rõ đội ngũ và chưa khóa thanh khoản.","Làm mất token LP hoặc NFT vị thế, vốn là bằng chứng sở hữu phần của bạn trong pool."],"faq":[{"q":"Cung cấp thanh khoản có lỗ được không?","a":"Có. Nếu giá hai token lệch mạnh, tổn thất tạm thời có thể vượt phí thu được, và giá token giảm cũng làm giảm giá trị vị thế."},{"q":"Token LP là gì?","a":"Token LP là biên nhận cho phần của bạn trong pool. Bạn cần nó để rút thanh khoản, và có thể dùng nó trong một số giao thức khác để nhận thêm thưởng."}],"title":"Pool thanh khoản là gì? Cách kiếm phí và rủi ro","description":"Pool thanh khoản (liquidity pool) là gì, người cung cấp thanh khoản kiếm phí thế nào và những rủi ro cần biết trước khi góp.","related":[["amm","Tạo lập thị trường tự động (AMM)","AMM (tạo lập thị trường tự động) là cơ chế của nhiều DEX dùng công thức toán học và pool thanh khoản để định giá và khớp giao dịch, thay cho sổ lệnh mua bán truyền thống."],["impermanent-loss","Tổn thất tạm thời (Impermanent loss)","Tổn thất tạm thời là phần giá trị bạn bị thiệt khi cung cấp thanh khoản cho pool so với việc chỉ giữ nguyên hai token, phát sinh khi giá của chúng thay đổi lệch nhau."],["yield-farming","Yield farming (Canh tác lợi suất)","Yield farming là chiến lược đưa crypto vào các giao thức DeFi như pool thanh khoản hoặc nền tảng cho vay để nhận phí, lãi và token thưởng, thường di chuyển vốn tới nơi trả lợi suất cao."],["rug-pull","Rug pull (Rút thảm)","Rug pull là khi đội ngũ dự án crypto đột ngột rút thanh khoản, bán tháo token hoặc biến mất cùng tiền của nhà đầu tư, khiến giá token gần như về 0."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"vi","term":"Perp DEX (Sàn hợp đồng vĩnh cửu phi tập trung)","aka":["perp DEX","DEX phái sinh","on-chain perpetuals"],"short":"Perp DEX là sàn phi tập trung cho phép giao dịch hợp đồng tương lai vĩnh cửu có đòn bẩy ngay trên blockchain, ký quỹ và thanh toán bằng ví của bạn thay vì tài khoản sàn tập trung.","body":[["Perp ",["DEX","dex"]," có nhiều kiến trúc: Hyperliquid chạy ",["sổ lệnh","order-book"]," trên ",["blockchain","blockchain"]," riêng của họ, dYdX dùng chuỗi ứng dụng riêng, còn GMX và các sàn tương tự cho bạn giao dịch với một ",["pool thanh khoản","liquidity-pool"]," dùng giá ",["oracle","oracle"],". Bạn nạp ",["USDC","usdc"]," hoặc tài sản ký quỹ từ ví, mở vị thế long hoặc short, và cũng trả funding rate như trên sàn tập trung."],"Ưu điểm: không phải gửi tiền cho công ty trung gian, vị thế và thanh lý minh bạch trên chuỗi, nhiều cặp mới được niêm yết nhanh. Nhược điểm: rủi ro hợp đồng và cầu nối, thanh khoản có thể mỏng hơn ở cặp nhỏ, và không có bộ phận hỗ trợ khi bạn mắc lỗi.","Chu kỳ funding, cách tính giá đánh dấu, cơ chế thanh lý và phí khác nhau giữa các perp DEX. Nhiều sàn tính funding theo giờ thay vì 8 giờ, hãy đọc trang thông số hợp đồng."],"example":"Giả sử bạn nạp 1.000 USDC vào một perp DEX và mở long BTC giá trị 5.000 USD, đòn bẩy 5x. Funding giả định là 0,001% mỗi giờ, tức khoảng 0,05 USD mỗi giờ hay 1,2 USD mỗi ngày bạn trả cho bên short. Nếu BTC giảm khoảng 18%, khoản lỗ cộng phí có thể đẩy ký quỹ xuống mức duy trì và vị thế bị thanh lý.","mistakes":["Nghĩ rằng giao dịch trên perp DEX không có rủi ro thanh lý vì là phi tập trung.","Quên tính funding theo giờ khi giữ vị thế nhiều ngày.","Bridge tiền vào perp DEX qua trang giả mạo hoặc cầu nối không chính thức."],"faq":[{"q":"Perp DEX khác sàn futures tập trung thế nào?","a":"Perp DEX để bạn ký quỹ từ ví và vị thế nằm trên chuỗi, còn sàn tập trung giữ tiền trong tài khoản của bạn trên sàn. Về cơ chế giao dịch, đòn bẩy, funding và thanh lý thì tương tự."},{"q":"Giao dịch trên perp DEX có cần KYC không?","a":"Nhiều perp DEX không yêu cầu KYC ở tầng giao thức, nhưng có thể chặn theo khu vực. Nghĩa vụ pháp lý và thuế vẫn tùy quốc gia của bạn."}],"title":"Perp DEX là gì? Giao dịch hợp đồng vĩnh cửu on-chain","description":"Perp DEX là gì, khác sàn futures tập trung ra sao, funding và thanh lý on-chain hoạt động thế nào cùng rủi ro cần biết.","related":[["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["dex","Sàn phi tập trung (DEX)","Sàn phi tập trung (DEX) là nơi giao dịch crypto trực tiếp từ ví của bạn qua hợp đồng thông minh, không cần nạp tiền vào tài khoản của một công ty trung gian."],["funding-rate","Funding rate (Tỷ lệ funding)","Funding rate là khoản thanh toán định kỳ giữa phe long và phe short trong hợp đồng tương lai vĩnh cửu, giúp giá hợp đồng bám sát giá spot."],["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản."]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"vi","term":"Copy trade (sao chép giao dịch)","aka":["copy trade","copy trading","sao chép lệnh","giao dịch sao chép"],"short":"Copy trade là tính năng cho phép bạn tự động sao chép các lệnh của một nhà giao dịch khác, gọi là trader dẫn dắt, theo tỷ lệ vốn mà bạn phân bổ.","body":["Các sàn như OKX, Bybit và Bitget đều có mục copy trade. Bạn chọn một trader dẫn dắt dựa trên lịch sử lợi nhuận, mức sụt giảm tối đa và số người theo dõi, rồi phân bổ một số vốn. Khi họ mở hoặc đóng lệnh, tài khoản của bạn làm theo tự động.",["Đa số copy trade diễn ra trên ",["hợp đồng tương lai vĩnh cửu","perpetual-futures"]," có ",["đòn bẩy","leverage"],", một số sàn có thêm copy trade spot. Trader dẫn dắt thường nhận phần chia lợi nhuận trên khoản lời của người sao chép. Tỷ lệ chia, cách tính và quy tắc khác nhau tùy sàn."],["Rủi ro lớn nhất là bạn giao quyền quyết định cho người khác. Thành tích quá khứ có thể đến từ một giai đoạn may mắn hoặc từ việc dùng đòn bẩy rất cao. Hãy đặt giới hạn vốn, mức ",["cắt lỗ","stop-loss"]," riêng cho phần copy và theo dõi thường xuyên."]],"example":["Giả sử bạn phân bổ 1.000 ",["USDT","usdt"]," để copy một trader có tỷ lệ chia lợi nhuận 10%. Sau một tháng, phần copy lời 200 USDT. Trader nhận 20 USDT, bạn còn 180 USDT lãi ròng trước phí giao dịch. Tháng sau, trader dùng đòn bẩy cao và gặp một cú giảm mạnh, phần copy lỗ 350 USDT. Nếu bạn đã đặt cắt lỗ cho toàn bộ phần copy ở mức 25%, hệ thống sẽ dừng sao chép khi lỗ đạt 250 USDT."],"mistakes":["Chọn trader chỉ vì lợi nhuận phần trăm cao trong vài tuần mà không xem mức sụt giảm tối đa.","Dồn toàn bộ tài khoản vào một trader duy nhất.","Không đặt cắt lỗ cho phần vốn copy và để hệ thống chạy mà không theo dõi."],"faq":[{"q":"Copy trade có chắc chắn lời không?","a":"Không. Bạn chịu cùng lãi lỗ với trader dẫn dắt, cộng thêm phí và độ trễ khớp lệnh, nên kết quả có thể khác với họ."},{"q":"Làm sao chọn trader để copy?","a":"Xem lợi nhuận trong thời gian dài, mức sụt giảm tối đa, đòn bẩy trung bình và số vốn họ tự quản lý. Ưu tiên người có kết quả ổn định hơn là đột biến."}],"title":"Copy trade là gì? Cách sao chép lệnh trên sàn crypto","description":"Copy trade giúp tự động sao chép lệnh của trader khác. Tìm hiểu cách chọn trader, chia lợi nhuận, rủi ro và cách đặt giới hạn.","related":[["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["leverage","Đòn bẩy (Leverage)","Đòn bẩy là việc dùng một khoản ký quỹ nhỏ để mở vị thế có giá trị lớn hơn nhiều lần, làm phóng đại cả lợi nhuận lẫn thua lỗ."],["risk-reward-ratio","Tỷ lệ rủi ro/lợi nhuận (Risk-reward ratio)","Tỷ lệ rủi ro/lợi nhuận (R:R) so sánh số tiền bạn có thể mất nếu chạm cắt lỗ với số tiền bạn có thể lãi nếu chạm chốt lời trong cùng một lệnh."],["grid-trading-bot","Bot giao dịch lưới (grid bot)","Bot giao dịch lưới là công cụ tự động đặt sẵn nhiều lệnh mua và bán ở các mức giá cách đều trong một vùng, để kiếm lời từ những lần giá dao động lên xuống."]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
